class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);Alerts.channel(this);setContent{DataFlowApp()}}}
class VM(private val store:Store,private val stats:Stats):ViewModel(){
 private val _s=MutableStateFlow(Snapshot());val s=_s.asStateFlow()
 init{viewModelScope.launch{store.flow.collectLatest{_s.value=it;refresh()}}}
 fun update(f:(Snapshot)->Snapshot)=viewModelScope.launch{val n=f(_s.value);_s.value=n;store.save(n)}
 fun refresh()=viewModelScope.launch{val x=_s.value; val z=ZoneId.systemDefault();val today=LocalDate.now().atStartOfDay(z).toInstant().toEpochMilli(); val now=System.currentTimeMillis();val period=x.plan.start.atStartOfDay(z).toInstant().toEpochMilli(); val tu=stats.mobile(today,now);val pu=stats.mobile(period,now);val n=x.copy(todayUsed=tu,measuredPeriod=pu,lastRefresh=if(tu!=null)now else x.lastRefresh);_s.value=n;store.save(n)}
 fun access()=stats.hasAccess(); fun json()=store.export(_s.value);fun csv()=store.csv(listOf(Daily(LocalDate.now().toString(),effectiveToday(),budget(),origin())))
 fun import(t:String)=update{store.import(t).copy(onboardingDone=true)}
 fun remaining():Long{val x=_s.value;if(x.demo)return 3_420*Units.MB;return x.manualRemaining ?: x.measuredPeriod?.let{maxOf(0,x.plan.totalBytes-it)} ?: x.plan.totalBytes}
 fun effectiveToday()=if(_s.value.demo)84*Units.MB else _s.value.todayUsed?:0
 fun origin()=when{_s.value.demo->DataOrigin.ESTIMATED;_s.value.todayUsed!=null->DataOrigin.MEASURED;_s.value.manualRemaining!=null->DataOrigin.MANUAL;else->DataOrigin.UNAVAILABLE}
 fun budget()=Engine.budget(remaining(),_s.value.plan)
}
@Composable fun DataFlowApp(){val c=LocalContext.current;val vm:VM=viewModel(factory=object:androidx.lifecycle.ViewModelProvider.Factory{override fun<T:ViewModel>create(m:Class<T>):T=VM(Store(c.applicationContext),Stats(c.applicationContext)) as T});val s by vm.s.collectAsState();var dark by remember{mutableStateOf(true)};val scheme=if(dark) darkColorScheme(primary=Color(0xFF55DDE0),secondary=Color(0xFF9B8CFF),background=Color(0xFF06101D),surface=Color(0xFF101E2D)) else lightColorScheme(primary=Color(0xFF006A6D));MaterialTheme(scheme){if(!s.onboardingDone)Onboarding(vm)else Home(vm,s,dark){dark=it}}}
@Composable fun Backdrop(content:@Composable BoxScope.()->Unit)=Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(MaterialTheme.colorScheme.background,MaterialTheme.colorScheme.surface))),content=content)
@Composable fun Onboarding(vm:VM){var page by remember{mutableIntStateOf(0)};var total by remember{mutableStateOf("5")};var days by remember{mutableStateOf("14")};var safety by remember{mutableIntStateOf(20)};val c=LocalContext.current;Backdrop{Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.SpaceBetween){Column{Text("DataFlow",fontSize=34.sp,fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary);Spacer(Modifier.height(28.dp));AnimatedContent(page,label="onboarding"){p->when(p){0->Step("Gardez le contrôle de votre forfait sans graphiques compliqués.","Tout reste sur votre appareil.");1->NumberStep("Volume disponible",total){total=it};2->NumberStep("Durée en jours",days){days=it};3->Column{Step("Marge de sécurité","Elle protège une réserve finale.");Slider(safety.toFloat(),{safety=it.toInt()},0f..100f);Text("$safety %")};4->Column{Step("Accès Android","DataFlow lit uniquement les statistiques réseau accessibles. Il ne peut ni couper Internet ni voir votre contenu.");Button({c.startActivity(Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS))}){Text("Ouvrir les réglages")};Text(if(vm.access())"Accès accordé" else "Accès non accordé — le mode manuel reste disponible")};else->Step("Prêt à commencer","Budget et projections seront recalculés localement.")}}};Button(onClick={if(page<5)page++ else {val p=Plan(Units.bytes(total.toDoubleOrNull()?:5.0,"Go"),LocalDate.now(),LocalDate.now().plusDays((days.toLongOrNull()?:14)-1),safety,if(vm.access())TrackingMode.AUTOMATIC else TrackingMode.MANUAL);vm.update{it.copy(plan=p,onboardingDone=true)}}},Modifier.fillMaxWidth()){Text(if(page==0)"Commencer" else if(page==5)"Lancer le suivi" else "Continuer")}}}}
@Composable fun Step(title:String,body:String){Text(title,fontSize=28.sp,fontWeight=FontWeight.SemiBold);Spacer(Modifier.height(12.dp));Text(body,style=MaterialTheme.typography.bodyLarge)}
@Composable fun NumberStep(title:String,v:String,on:(String)->Unit){Column{Step(title,"Saisissez une valeur positive.");OutlinedTextField(v,on,label={Text("Valeur")},singleLine=true)}}
@Composable fun Home(vm:VM,s:Snapshot,dark:Boolean,onDark:(Boolean)->Unit){var tab by remember{mutableIntStateOf(0)};Scaffold(bottomBar={NavigationBar{listOf("Aujourd’hui" to Icons.Outlined.Home,"Applications" to Icons.Outlined.Apps,"Historique" to Icons.Outlined.BarChart,"Réglages" to Icons.Outlined.Settings).forEachIndexed{i,x->NavigationBarItem(tab==i,{tab=i},{Icon(x.second,x.first)},{Text(x.first)})}}}){pad->Backdrop{Box(Modifier.padding(pad)){when(tab){0->Today(vm,s);1->Apps(vm,s);2->History(vm,s);else->SettingsPage(vm,s,dark,onDark)}}}}}
@Composable fun CardBox(content:@Composable ColumnScope.()->Unit)=Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(24.dp),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surface.copy(alpha=.86f))){Column(Modifier.padding(20.dp),content=content)}
@Composable fun Today(vm:VM,s:Snapshot){val remaining=vm.remaining();val budget=vm.budget();val used=vm.effectiveToday();LazyColumn(Modifier.fillMaxSize().padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Aujourd’hui",fontSize=30.sp,fontWeight=FontWeight.Bold);if(s.demo)AssistChip({}, {Text("Données de démonstration")})};IconButton({vm.refresh()}){Icon(Icons.Outlined.Refresh,"Rafraîchir")}}};item{CardBox{Text("Tu peux utiliser environ",style=MaterialTheme.typography.titleMedium);Text(Units.format(budget),fontSize=42.sp,fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary);Spacer(Modifier.height(14.dp));ProgressArc(if(budget>0)used.toFloat()/budget else 0f);Text("${Units.format(used)} utilisés aujourd’hui");Text(Engine.status(used,budget),fontWeight=FontWeight.SemiBold);Text("Origine : ${vm.origin().name.lowercase()}")}};item{CardBox{Text("Projection",fontWeight=FontWeight.Bold);val avg=if(s.measuredPeriod!=null) s.measuredPeriod/ maxOf(1,Duration.between(s.plan.start.atStartOfDay(),LocalDate.now().plusDays(1).atStartOfDay()).toDays()) else 0;Text(if(avg>0)"À ce rythme, il resterait environ ${Units.format(Engine.projectedRemaining(remaining,avg,s.plan))} le dernier jour." else "Les données sont insuffisantes pour établir une projection fiable.")}};item{CardBox{Text("Résumé",fontWeight=FontWeight.Bold);Text("Restant : ${Units.format(remaining)}");Text("Jours restants : ${Engine.daysRemaining(s.plan)}");Text("Réserve : ${Units.format(Engine.reserve(s.plan))}");Text("Dernière actualisation : ${if(s.lastRefresh==0L)"jamais" else java.text.DateFormat.getDateTimeInstance().format(s.lastRefresh)}")}};item{Simulator(vm)}}}
@Composable fun ProgressArc(p:Float){val primary=MaterialTheme.colorScheme.primary;Canvas(Modifier.fillMaxWidth().height(130.dp).semantics{contentDescription="Progression du budget quotidien ${(p*100).toInt()} pour cent"}){val st=18.dp.toPx();drawArc(Color.Gray.copy(.25f),180f,180f,false,style=Stroke(st,cap=StrokeCap.Round));drawArc(primary,180f,180f*p.coerceIn(0f,1.3f),false,style=Stroke(st,cap=StrokeCap.Round))}}
@Composable fun Simulator(vm:VM){var minutes by remember{mutableStateOf("60")};var activity by remember{mutableStateOf("YouTube 720p")};val rates=mapOf("YouTube 720p" to Triple(500,900,1500),"Musique" to Triple(40,100,180),"Navigation GPS" to Triple(5,15,40),"ChatGPT texte" to Triple(1,5,20));CardBox{Text("Simuler",fontWeight=FontWeight.Bold);var open by remember{mutableStateOf(false)};Button({open=true}){Text(activity)};DropdownMenu(open,{open=false}){rates.keys.forEach{item->DropdownMenuItem(text={Text(item)},onClick={activity=item;open=false})}};OutlinedTextField(minutes,{minutes=it},label={Text("Minutes")});val r=rates[activity]!!;val factor=(minutes.toDoubleOrNull()?:0.0)/60;Text("Estimation : ${Units.format((r.first*factor*Units.MB).toLong())} à ${Units.format((r.third*factor*Units.MB).toLong())}");Text("Valeur centrale : ${Units.format((r.second*factor*Units.MB).toLong())}")}}
@Composable fun Apps(vm:VM,s:Snapshot){Column(Modifier.padding(20.dp)){Text("Applications",fontSize=30.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(16.dp));CardBox{Text("Détail par application",fontWeight=FontWeight.Bold);Text("Les données détaillées par application ne sont pas disponibles de façon fiable sur tous les appareils. DataFlow n’invente aucun nom ni volume.");Text(if(vm.access())"Accès aux statistiques accordé." else "L’accès aux statistiques d’utilisation est nécessaire.")}}}
@Composable fun History(vm:VM,s:Snapshot){val used=vm.effectiveToday();val b=vm.budget();val primary=MaterialTheme.colorScheme.primary;Column(Modifier.padding(20.dp)){Text("Historique",fontSize=30.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(16.dp));CardBox{Text("Consommation quotidienne",fontWeight=FontWeight.Bold);Canvas(Modifier.fillMaxWidth().height(180.dp).semantics{contentDescription="Aujourd’hui ${Units.format(used)}, budget ${Units.format(b)}"}){val max=maxOf(1L,used,b).toFloat();drawLine(Color.Gray,Offset(0f,size.height*(1-b/max)),Offset(size.width,size.height*(1-b/max)),strokeWidth=3f);drawRect(primary,Offset(size.width*.35f,size.height*(1-used/max)),androidx.compose.ui.geometry.Size(size.width*.3f,size.height*used/max))};Text("Aujourd’hui : ${Units.format(used)} — budget ${Units.format(b)}")}}}
@Composable fun SettingsPage(vm:VM,s:Snapshot,dark:Boolean,onDark:(Boolean)->Unit){val c=LocalContext.current;val createJson=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){u->u?.let{c.contentResolver.openOutputStream(it)?.use{o->o.write(vm.json().toByteArray())}}};val createCsv=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("text/csv")){u->u?.let{c.contentResolver.openOutputStream(it)?.use{o->o.write(vm.csv().toByteArray())}}};val import=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u->u?.let{runCatching{c.contentResolver.openInputStream(it)!!.bufferedReader().readText()}.onSuccess(vm::import)}};val notif=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){};LazyColumn(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Réglages",fontSize=30.sp,fontWeight=FontWeight.Bold)};item{CardBox{Text("Forfait",fontWeight=FontWeight.Bold);Text("${Units.format(s.plan.totalBytes)} · ${s.plan.safety}% de réserve · ${s.plan.mode}");Button({vm.update{it.copy(manualRemaining=maxOf(0,vm.remaining()-100*Units.MB),plan=it.plan.copy(mode=TrackingMode.MANUAL))}}){Text("Ajouter un relevé manuel (-100 Mo)")}}};item{CardBox{Text("Affichage",fontWeight=FontWeight.Bold);Row(verticalAlignment=Alignment.CenterVertically){Text("Thème sombre",Modifier.weight(1f));Switch(dark,onDark)};Row(verticalAlignment=Alignment.CenterVertically){Text("Réduire les effets visuels",Modifier.weight(1f));Switch(s.reduceEffects,{v->vm.update{it.copy(reduceEffects=v)}})}}};item{CardBox{Text("Notifications",fontWeight=FontWeight.Bold);Row(verticalAlignment=Alignment.CenterVertically){Text("Alertes locales",Modifier.weight(1f));Switch(s.notifications,{v->if(v && android.os.Build.VERSION.SDK_INT>=33)notif.launch(Manifest.permission.POST_NOTIFICATIONS);vm.update{it.copy(notifications=v)}})};Text("Android peut retarder les vérifications en arrière-plan.")}};item{CardBox{Text("Données",fontWeight=FontWeight.Bold);Row{Button({createJson.launch("DataFlow-backup.json")}){Text("Export JSON")};Spacer(Modifier.width(8.dp));Button({createCsv.launch("DataFlow-history.csv")}){Text("CSV")}};Button({import.launch(arrayOf("application/json"))}){Text("Importer JSON")};Row(verticalAlignment=Alignment.CenterVertically){Text("Mode démonstration",Modifier.weight(1f));Switch(s.demo,{v->vm.update{it.copy(demo=v)}})}}};item{CardBox{Text("Vie privée",fontWeight=FontWeight.Bold);Text("Données stockées uniquement sur l’appareil. Aucune vente, synchronisation externe, collecte analytique ou transmission à un serveur. DataFlow ne déclare pas la permission INTERNET.")}};item{CardBox{Text("Limites Android",fontWeight=FontWeight.Bold);Text("Les compteurs peuvent être retardés ou indisponibles selon le constructeur, la SIM et la version Android. DataFlow ne peut pas couper les données d’autres applications.");Button({c.startActivity(Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS))}){Text("Accès aux statistiques")}}}}
